package app.dawnbreaker.mobile;
import static org.junit.Assert.*;
import android.content.*;import android.webkit.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @LooperMode(LooperMode.Mode.PAUSED)
public class OfflineTest {
 @Test public void largeEncryptedVaultCanBeReadWithoutExpandingOtherResourceLimits()throws Exception{
  Context c=RuntimeEnvironment.getApplication();android.net.ConnectivityManager manager=(android.net.ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);org.robolectric.shadows.ShadowConnectivityManager shadow=Shadows.shadowOf(manager);shadow.setActiveNetworkInfo(org.robolectric.shadows.ShadowNetworkInfo.newInstance(android.net.NetworkInfo.DetailedState.CONNECTED,android.net.ConnectivityManager.TYPE_WIFI,0,true,true));shadow.setNetworkCapabilities(manager.getActiveNetwork(),Shadows.shadowOf(org.robolectric.shadows.ShadowNetworkCapabilities.newInstance()).addCapability(android.net.NetworkCapabilities.NET_CAPABILITY_INTERNET));
  byte[] chunk=new byte[1024*1024];Arrays.fill(chunk,(byte)'A');int length=35*chunk.length+17;ServerSocket server=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"));
  Thread worker=new Thread(()->{try(Socket socket=server.accept()){BufferedReader input=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.US_ASCII));String line;while((line=input.readLine())!=null&&!line.isEmpty()){}OutputStream out=socket.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+length+"\r\nConnection: close\r\n\r\n{\"ciphertext\":\"").getBytes(StandardCharsets.US_ASCII));for(int i=0;i<35;i++)out.write(chunk);out.write("\"}".getBytes(StandardCharsets.US_ASCII));out.flush();}catch(IOException ignored){}});worker.setDaemon(true);worker.start();
  try{OfflineProxy proxy=new OfflineProxy(c,"http://127.0.0.1:"+server.getLocalPort());WebResourceResponse response=proxy.get("/api/plugins/vault?check=145",Collections.emptyMap());assertEquals(200,response.getStatusCode());byte[] body=OfflineProxy.read(response.getData(),46*1024*1024);assertEquals(length,body.length);assertEquals((byte)'{',body[0]);assertEquals((byte)'}',body[body.length-1]);assertNull(response.getResponseHeaders().get("X-Dawn-Offline"));assertEquals(24*1024*1024,OfflineProxy.resourceLimit("/api/plugins/library"));assertEquals(64*1024*1024,OfflineProxy.resourceLimit("/api/plugins/companion/media/123"));}finally{server.close();worker.join(1000);}
 }
 @Test public void cachedBootstrapDocumentAndAtlasSurviveServerShutdownWithoutLeakingAccounts()throws Exception{
  Context c=RuntimeEnvironment.getApplication();String uid="bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";AtomicInteger requests=new AtomicInteger();ServerSocket server=new ServerSocket(0,5,InetAddress.getByName("127.0.0.1"));Thread worker=new Thread(()->{while(!server.isClosed())try(Socket socket=server.accept()){requests.incrementAndGet();BufferedReader reader=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.US_ASCII));String route=reader.readLine().split(" ")[1];String line;while((line=reader.readLine())!=null&&!line.isEmpty()){}String body=route.equals("/api/bootstrap")?"{\"user\":{\"id\":\""+uid+"\"}}":route.endsWith("/live")?"{\"fetched_at\":\"2026-11-04T00:00:00Z\",\"stale\":false}":"{\"markdown\":\"$E=mc^2$\"}";byte[] bytes=body.getBytes(StandardCharsets.UTF_8);OutputStream out=socket.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+bytes.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(bytes);out.flush();}catch(IOException ignored){}});worker.setDaemon(true);worker.start();
  android.net.ConnectivityManager manager=(android.net.ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);org.robolectric.shadows.ShadowConnectivityManager shadow=Shadows.shadowOf(manager);shadow.setActiveNetworkInfo(org.robolectric.shadows.ShadowNetworkInfo.newInstance(android.net.NetworkInfo.DetailedState.CONNECTED,android.net.ConnectivityManager.TYPE_WIFI,0,true,true));shadow.setNetworkCapabilities(manager.getActiveNetwork(),Shadows.shadowOf(org.robolectric.shadows.ShadowNetworkCapabilities.newInstance()).addCapability(android.net.NetworkCapabilities.NET_CAPABILITY_INTERNET));
  OfflineProxy proxy=new OfflineProxy(c,"http://127.0.0.1:"+server.getLocalPort());Map<String,String> headers=Collections.emptyMap();
  try{assertEquals(200,proxy.get("/api/bootstrap",headers).getStatusCode());assertEquals(uid,OfflineProxy.prefs(c).getString("account",""));assertEquals(200,proxy.get("/api/plugins/library/nodes/doc",headers).getStatusCode());assertEquals(200,proxy.get("/api/plugins/atlas/live",headers).getStatusCode());}finally{server.close();worker.join(1000);}
  shadow.setNetworkCapabilities(manager.getActiveNetwork(),new android.net.NetworkCapabilities());int before=requests.get();OfflineProxy restarted=new OfflineProxy(c,"http://127.0.0.1:9");WebResourceResponse document=restarted.get("/api/plugins/library/nodes/doc",headers);assertEquals(200,document.getStatusCode());assertEquals("1",document.getResponseHeaders().get("X-Dawn-Offline"));assertTrue(new String(OfflineProxy.read(document.getData(),65536),StandardCharsets.UTF_8).contains("E=mc^2"));
  JSONObject atlas=new JSONObject(new String(OfflineProxy.read(restarted.get("/api/plugins/atlas/live",headers).getData(),65536),StandardCharsets.UTF_8));assertTrue(atlas.getBoolean("stale"));assertTrue(atlas.getBoolean("offline"));assertEquals(before,requests.get());
  OfflineProxy.prefs(c).edit().putString("account","cccccccccccccccccccccccccccccccc").commit();assertEquals(503,restarted.get("/api/plugins/library/nodes/doc",headers).getStatusCode());
  OfflineProxy.prefs(c).edit().remove("account").commit();assertEquals(401,restarted.get("/api/bootstrap",headers).getStatusCode());
 }
 @Test public void listeningLedgerIsDurableAccountScopedAndNotDeletedByCacheCleanup()throws Exception{
  Context c=RuntimeEnvironment.getApplication();java.lang.reflect.Field field=PlaybackLedger.class.getDeclaredField("helper");field.setAccessible(true);field.set(null,null);
  MediaStore.prefs(c).edit().putString("account","dddddddddddddddddddddddddddddddd").commit();PlaybackLedger ledger=new PlaybackLedger(c);ledger.add("001",12.5,1700000020);assertEquals(12.5,new PlaybackLedger(c).pendingSeconds(),.001);
  OfflineProxy.clear(c);MusicCache.clear(c);assertEquals(12.5,ledger.pendingSeconds(),.001);
  MediaStore.prefs(c).edit().putString("account","eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee").commit();assertEquals(0,ledger.pendingSeconds(),.001);
  MediaStore.prefs(c).edit().putString("account","dddddddddddddddddddddddddddddddd").commit();assertEquals(12.5,ledger.pendingSeconds(),.001);
 }
}
